  if(receiving){runOnMainSync(()->{engine.setDirectory(tree());engine.prepareOnlineReceiver();});waitFor(()->!engine.isActive()&&engine.pairingCode().startsWith("CTPA5O|"),45000,"OFFER_NOT_READY");taskId=engine.gate.current().getString("id");markTask();phase="offer-ready";}
